import subprocess
import sys


def run_solution(person):
    return subprocess.run(
        [sys.executable, "solution.py"],
        input=person + "\n",
        text=True,
        capture_output=True,
    )


def run_solution_with_score_type_check(person):
    wrapper = (
        "import runpy\n"
        "values = runpy.run_path('solution.py', run_name='__main__')\n"
        "print('SCORES_ARE_INTS:' + str(all(isinstance(v, int) for v in values['score_dict'].values())))\n"
    )
    return subprocess.run(
        [sys.executable, "-c", wrapper],
        input=person + "\n",
        text=True,
        capture_output=True,
    )

def test_person_score_and_status_mappings():
    expected = {
        "john": ("90", "active"),
        "jane": ("100", "active"),
        "james": ("0", "inactive"),
    }
    for person, (score, status) in expected.items():
        result = run_solution(person)
        assert result.returncode == 0, result.stderr
        assert result.stdout.splitlines() == [score, status]

def test_score_dictionary_values_are_integers():
    result = run_solution_with_score_type_check("john")
    assert result.returncode == 0, result.stderr
    assert result.stdout.splitlines()[-1] == "SCORES_ARE_INTS:True"

